// Task-local runner: initialize the slack-api skill skeleton via the
// skill-creator init script, then remove placeholder example files that
// this skill does not need (assets are unused; example script/reference
// will be replaced by real content).
import { execFileSync } from 'node:child_process';
import { existsSync, rmSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';

const cwd = process.cwd();
const initScript = path.join(cwd, '.codex/skills/skill-creator/scripts/init_skill.cjs');
const skillDir = path.join(cwd, 'slack-api');

if (!existsSync(initScript)) {
  console.error(`init_skill.cjs not found at ${initScript}`);
  process.exit(1);
}

// 1. Run the official init script
const out = execFileSync(process.execPath, [initScript, 'slack-api', '--path', cwd], {
  encoding: 'utf8',
  stdio: ['ignore', 'pipe', 'inherit'],
});
process.stdout.write(out);

// 2. Remove placeholder files created by the template
const placeholders = [
  path.join(skillDir, 'scripts/example_script.cjs'),
  path.join(skillDir, 'references/example_reference.md'),
  path.join(skillDir, 'assets/example_asset.txt'),
];
for (const p of placeholders) rmSync(p, { force: true });
rmSync(path.join(skillDir, 'assets'), { recursive: true, force: true });

// 3. Print the resulting tree for confirmation
function tree(dir, prefix = '') {
  for (const entry of readdirSync(dir).sort()) {
    const full = path.join(dir, entry);
    const isDir = statSync(full).isDirectory();
    console.log(`${prefix}${isDir ? '📁' : '📄'} ${entry}`);
    if (isDir) tree(full, prefix + '  ');
  }
}
console.log('\nSkill directory after init + cleanup:');
tree(skillDir);

